import Link from 'next/link'
import type { ReactNode } from 'react'
import styles from './Hero.module.css'
import { Eyebrow } from './Eyebrow'
import { Underline } from './Underline'

interface HeroCta {
  label: string
  href: string
}

interface HeroProps {
  title: string
  /** 제목 위에 놓이는 작은 라벨: 이 사이트가 무엇인지 */
  eyebrow?: string
  /** 제목 아래 메시지 */
  description?: string | ReactNode
  /** 주요 행동 버튼 */
  cta?: HeroCta
  /** 보조 행동 버튼 (테두리형) */
  secondaryCta?: HeroCta
  /** 제목 안에서 손그림 밑줄을 칠 키워드 (정확히 일치하는 부분만) */
  underline?: string
  /** 레이아웃 — center(기본 가운데 정렬) | split(좌측 2단: 제목 왼쪽 / 설명 오른쪽) */
  align?: 'center' | 'split'
}

/** 제목에서 underline 키워드만 손그림 밑줄로 감싼다 */
function renderTitle(title: string, underline?: string): ReactNode {
  if (!underline) return title
  const idx = title.indexOf(underline)
  if (idx === -1) return title
  return (
    <>
      {title.slice(0, idx)}
      <Underline>{underline}</Underline>
      {title.slice(idx + underline.length)}
    </>
  )
}

export function Hero({ title, eyebrow, description, cta, secondaryCta, underline, align = 'center' }: HeroProps) {
  const titleNode = renderTitle(title, underline)
  const ctaNode = (cta || secondaryCta) && (
    <div className={styles.actions}>
      {cta && (
        <Link className={styles.cta} href={cta.href}>
          {cta.label}
        </Link>
      )}
      {secondaryCta && (
        <Link className={`${styles.cta} ${styles.ctaSecondary}`} href={secondaryCta.href}>
          {secondaryCta.label}
        </Link>
      )}
    </div>
  )

  if (align === 'split') {
    return (
      <div className={`${styles.hero} ${styles.split}`} data-landing-hero>
        <div className={styles.splitInner}>
          <div className={styles.splitLeft}>
            <div className={styles.starGlow} aria-hidden="true" />
            <StarMark />
            {eyebrow && (
              <span className={styles.eyebrowReveal}>
                <Eyebrow>{eyebrow}</Eyebrow>
              </span>
            )}
            <h1 className={styles.title}>{titleNode}</h1>
          </div>
          <div className={styles.splitRight}>
            {description && <div className={styles.description}>{description}</div>}
            {ctaNode}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className={styles.hero} data-landing-hero>
      <div className={styles.inner}>
        <div className={styles.starGlow} aria-hidden="true" />
        <StarMark />
        {eyebrow && (
          <span className={styles.eyebrowReveal}>
            <Eyebrow>{eyebrow}</Eyebrow>
          </span>
        )}
        <h1 className={styles.title}>{titleNode}</h1>
        {description && <div className={styles.description}>{description}</div>}
        {ctaNode}
      </div>
    </div>
  )
}

